	protected List<InsuredObject> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of InsuredObjects:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all InsuredObject : " );        
		List<InsuredObject> collection  = new ArrayList<>();

		try {
			// call the static get method on the InsuredObjectService
			collection = InsuredObjectService.getInsuredObjectInstance().getAllInsuredObject();
			assertNotNull( collection, "An Empty collection of InsuredObject was incorrectly returned.");
			
			// Now print out the values
			InsuredObject entity = null;            
			Iterator<InsuredObject> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getInsuredObjectId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

